const messageMaps: Record<Exclude<LanguageCode, 'en'>, Record<string, string>> = {
  hi: {}, bn: {}, mr: {}, ta: {}, te: {},
};
for (const row of rows.trim().split('\n')) {
  const [key, hi, bn, mr, ta, te] = row.split('|');
  if (!key) continue;
  messageMaps.hi[key] = hi || key;
  messageMaps.bn[key] = bn || key;
  messageMaps.mr[key] = mr || key;
  messageMaps.ta[key] = ta || key;
  messageMaps.te[key] = te || key;
}

export const normalizeTranslationKey = (value: string) => value.replace(/\s+/g, ' ').trim();
export const t = (source: string, language?: LanguageCode): string => {
  const activeLanguage = language || getSavedLanguage();
  if (activeLanguage === 'en') return source;
  return messageMaps[activeLanguage]?.[normalizeTranslationKey(source)] || source;
};
export const getSavedLanguage = (): LanguageCode => {
  if (typeof window === 'undefined') return 'en';
  const stored = window.localStorage.getItem('udyamsync-language');
  return LANGUAGES.some(option => option.code === stored) ? (stored as LanguageCode) : 'en';
};
